'use strict';
(() => {
  const languages=['zh','en','fr','es','eu'],A=()=>window.YV_APP,B=()=>window.YV_BUILDER,E=v=>A().esc(v);
  const copy={
    export:['导出方案','Export plan','Exporter le plan','Exportar el plan','Esportatu plana'],
    review:['检查内容','Review selections','Vérifier les choix','Revisar selección','Berrikusi hautaketa'],
    figures:['流程与图表','Workflow & figures','Flux et figures','Flujo y figuras','Fluxua eta irudiak'],
    current:['当前方案','Current plan','Plan actuel','Plan actual','Uneko plana'],
    preview:['打开预览','Open preview','Ouvrir l’aperçu','Abrir vista previa','Ireki aurrebista'],
    previewHelp:['查看正文、流程图与结果表字段。','Review the document, workflow and result-table fields.','Consultez le document, le flux et les champs des résultats.','Revisa el documento, el flujo y los campos de resultados.','Berrikusi dokumentua, fluxua eta emaitza-taulako eremuak.'],
    format:['选择文件','Choose a file','Choisir un fichier','Elegir un archivo','Hautatu fitxategia'],
    document:['研究方案','Research plan','Plan de recherche','Plan de investigación','Ikerketa-plana'],
    documentHint:['正文、方法、marker 与参考文献。打开后可打印为 PDF。','Document, methods, markers and references. Open the file to print to PDF.','Document, méthodes, marqueurs et références. Ouvrez le fichier pour imprimer en PDF.','Documento, métodos, marcadores y referencias. Abre el archivo para imprimir como PDF.','Dokumentua, metodoak, markatzaileak eta erreferentziak. Ireki fitxategia PDF gisa inprimatzeko.'],
    workbook:['研究工作表','Research workbook','Classeur de recherche','Libro de investigación','Ikerketa-liburua'],
    workbookHint:['指标、参数、marker、证据与来源分表，保留筛选。','Separate, filterable sheets for metrics, parameters, markers, evidence and sources.','Feuilles filtrables : indicateurs, paramètres, marqueurs, preuves et sources.','Hojas filtrables de indicadores, parámetros, marcadores, evidencia y fuentes.','Metrikak, parametroak, markatzaileak, ebidentzia eta iturriak orri iragazgarrietan.'],
    diagram:['流程图','Workflow diagrams','Schémas du flux','Diagramas del flujo','Fluxu-diagramak'],
    diagramHint:['可编辑文字的矢量图，适合汇报和排版。','Vector artwork with editable text for presentations and layouts.','Graphiques vectoriels avec texte éditable pour présentations et mise en page.','Gráficos vectoriales con texto editable para presentaciones y maquetación.','Testu editagarriko irudi bektorialak aurkezpenetarako eta maketaziorako.'],
    references:['参考文献','References','Références','Referencias','Erreferentziak'],
    referencesHint:['随已选方法与证据整理，自动去重。','Compiled from selected methods and evidence, with duplicates removed.','Références des méthodes et preuves choisies, sans doublons.','Referencias de métodos y evidencia seleccionados, sin duplicados.','Hautatutako metodoen eta ebidentziaren erreferentziak, bikoizturik gabe.'],
    appearance:['语言与排版','Language & typography','Langue et typographie','Idioma y tipografía','Hizkuntza eta tipografia'],
    optionsHelp:['仅改变导出文件；自填内容与论文题名保留原文。','Applies to exported files. Your text and article titles retain their original language.','S’applique aux fichiers exportés. Vos textes et les titres restent dans leur langue d’origine.','Se aplica a los archivos exportados. Tus textos y los títulos conservan su idioma original.','Esportatutako fitxategiei aplikatzen zaie. Zure testuak eta artikuluen izenburuak jatorrizko hizkuntzan mantentzen dira.'],
    style:['配色','Palette','Palette','Paleta','Paleta'],
    navy:['深蓝','Midnight','Bleu nuit','Azul noche','Gau-urdina'],teal:['青绿','Teal','Bleu-vert','Verde azulado','Urdin-berdea'],mono:['石墨','Graphite','Graphite','Grafito','Grafitoa'],
    download:['下载文件','Download file','Télécharger','Descargar archivo','Deskargatu fitxategia'],
    extra:['更多格式与方案备份','More formats & plan backup','Autres formats et sauvegarde','Más formatos y copia del plan','Formatu gehiago eta planaren babeskopia'],
    backup:['方案备份','Plan backup','Sauvegarde du plan','Copia del plan','Planaren babeskopia'],
    backupHelp:['JSON 可重新导入工作站，保留选择与参数。','Reimport JSON into the workstation to restore selections and parameters.','Réimportez le JSON pour restaurer les choix et paramètres.','Reimporta el JSON para restaurar selecciones y parámetros.','Inportatu JSONa berriro hautaketak eta parametroak berreskuratzeko.'],
    text:['可编辑正文','Editable text','Texte éditable','Texto editable','Testu editagarria'],
    data:['指标数据表','Metric data table','Table des indicateurs','Tabla de indicadores','Metriken datu-taula'],
    code:['流程源文件','Workflow source','Source du flux','Fuente del flujo','Fluxuaren iturburua'],
    content:['导出内容','Included content','Contenu exporté','Contenido exportado','Esportatutako edukia'],
    checksHint:['查看所需数据、待填参数和 marker 面板。','Review required inputs, outstanding parameters and the marker panel.','Vérifiez les données requises, les paramètres à renseigner et le panel de marqueurs.','Revisa los datos necesarios, los parámetros pendientes y el panel de marcadores.','Berrikusi beharrezko datuak, falta diren parametroak eta markatzaile-panela.'],
    diagramKind:['图类型','Diagram','Schéma','Diagrama','Diagrama'],
    referencesKind:['引文格式','Citation format','Format bibliographique','Formato bibliográfico','Aipamen-formatua'],
    fullPreview:['预览完整方案','Preview full plan','Aperçu du plan complet','Vista previa del plan completo','Plan osoaren aurrebista'],
    map:['研究结构图','Research structure','Structure du plan','Estructura del plan','Planaren egitura'],
    dependencies:['步骤依赖图','Step dependencies','Dépendances des étapes','Dependencias entre pasos','Urratsen mendekotasunak'],
    loading:['正在生成预览…','Preparing preview…','Préparation de l’aperçu…','Preparando la vista previa…','Aurrebista prestatzen…'],
    selected:['仅包含当前方案中已选择的内容。','Includes the current plan selection.','Contient les éléments choisis dans le plan.','Incluye la selección del plan actual.','Uneko planean hautatutako edukia barne hartzen du.'],
    noChecks:['当前没有需要补充的项目。','No outstanding items in this check.','Aucun élément à compléter dans ce contrôle.','No hay elementos pendientes en esta revisión.','Egiaztapen honetan ez dago osatu beharreko elementurik.']
  };
  const T=k=>copy[k]?.[Math.max(0,languages.indexOf(A()?.prefs().language))]||k;
  let activeTab='export',format='document',diagram='map',citation='apa',previewTimer,paperObserver;
  const formats={document:{icon:'literature',extension:'HTML',attribute:'data-v3',action:'export-html'},workbook:{icon:'chart',extension:'XLSX',attribute:'data-export6',action:'xlsx'},diagram:{icon:'workflow',extension:'SVG'},references:{icon:'literature',extension:'APA 7'}};
  const theme=()=>{try{return localStorage.getItem('yv.export.theme')||'navy'}catch{return 'navy'}};
  const button=(text,attributes='',className='btn')=>`<button type="button" class="${className}" ${attributes}>${text}</button>`;
  function outputControls(){const o=window.YV_EXPORT_LAYOUT.options(),t=k=>window.YV_EXPORT_LAYOUT.text(k,A().prefs().language);return `<fieldset class="ex15-output"><legend>${E(T('appearance'))}</legend><div class="ex15-output-grid"><label>${E(t('language'))}<select data-export-option="language">${[['zh','中文'],['en','English'],['fr','Français'],['es','Español'],['eu','Euskara']].map(([v,n])=>`<option value="${v}" ${o.language===v?'selected':''}>${n}</option>`).join('')}</select></label><label>${E(t('font'))}<select data-export-option="font">${Object.keys(window.YV_EXPORT_LAYOUT.fonts).map(v=>`<option value="${v}" ${o.font===v?'selected':''}>${E(t(v))}</option>`).join('')}</select></label></div><div class="ex15-palettes" role="group" aria-label="${E(T('style'))}">${['navy','teal','mono'].map(v=>button(`<i aria-hidden="true"></i>${E(T(v))}`,`data-ex15-theme="${v}" aria-pressed="${theme()===v}"`,'ex15-palette')).join('')}</div><p>${E(T('optionsHelp'))}</p></fieldset>`;}
  function extra(){return `<details class="ex15-extra"><summary>${E(T('extra'))}${A().icon('plus')}</summary><div class="ex15-extra-grid"><div><strong>${E(T('backup'))}</strong><p>${E(T('backupHelp'))}</p>${button('JSON','data-build="export-json"')}</div><div><strong>${E(T('text'))}</strong>${button('Markdown','data-build="export-md"')}</div><div><strong>${E(T('data'))}</strong>${button('TSV','data-v3="export-qc"')}</div><div><strong>${E(T('code'))}</strong>${button('Mermaid','data-build="export-mermaid"')}</div></div></details>`;}
  function exportMarkup(){const p=B().getPlan();return `<div class="ex15-export-layout"><div class="ex15-preview-column"><div class="ex15-document-label"><span>${E(T('current'))}</span><span>YEASTVAR1011</span></div><button type="button" class="ex15-paper" data-ex15="preview" aria-label="${E(T('fullPreview'))}"><span class="ex15-paper-frame"><span class="ex15-paper-loading">${E(T('loading'))}</span><iframe title="${E(T('preview'))}" tabindex="-1" inert sandbox referrerpolicy="no-referrer"></iframe></span><span class="ex15-paper-action">${A().icon('view')}${E(T('preview'))}${A().icon('arrow')}</span></button><div class="ex15-selection"><span>${E(T('content'))}</span>${[['tools','#tools'],['metrics','#quality'],['markers','#markers?view=panel']].map(([key,url])=>`<a href="${url}">${E(window.YV_PLAN.text(key))}<strong data-pw-count="${key}">${p[key].length}</strong>${A().icon('arrow')}</a>`).join('')}</div><p class="ex15-preview-help">${E(T('previewHelp'))}</p></div><div class="ex15-settings-column"><fieldset class="ex15-formats"><legend>${E(T('format'))}</legend>${Object.entries(formats).map(([id,f])=>`<label class="ex15-format"><input type="radio" name="ex15-format" value="${id}" ${format===id?'checked':''}><span class="ex15-file-icon">${A().icon(f.icon)}</span><span><strong>${E(T(id))}</strong><small>${E(T(id+'Hint'))}</small></span><b>${f.extension}</b></label>`).join('')}</fieldset><div class="ex15-subformat"></div>${outputControls()}<div class="ex15-download"><p>${E(T('selected'))}</p><button type="button" class="btn btn-primary ex15-primary" id="ex15-download"></button></div></div></div>${extra()}`;}
  function updateFormat(){const root=document.querySelector('.ex15-export');if(!root)return;const sub=root.querySelector('.ex15-subformat'),primary=root.querySelector('#ex15-download');let f=formats[format],extension=f.extension;if(format==='diagram'){sub.innerHTML=`<label>${E(T('diagramKind'))}<select data-ex15-diagram><option value="map" ${diagram==='map'?'selected':''}>${E(T('map'))}</option><option value="workflow" ${diagram==='workflow'?'selected':''}>${E(T('dependencies'))}</option></select></label>`;f={...f,attribute:diagram==='map'?'data-export6':'data-build',action:diagram==='map'?'map':'export-svg'};}else if(format==='references'){sub.innerHTML=`<label>${E(T('referencesKind'))}<select data-ex15-citation><option value="apa" ${citation==='apa'?'selected':''}>APA 7 · TXT</option><option value="csl" ${citation==='csl'?'selected':''}>CSL-JSON</option></select></label>`;f={...f,attribute:'data-export6',action:citation};extension=citation==='apa'?'TXT':'JSON';}else sub.replaceChildren();for(const key of ['data-v3','data-build','data-export6'])primary.removeAttribute(key);primary.setAttribute(f.attribute,f.action);primary.innerHTML=A().icon('download')+E(T('download'))+`<span>${extension}</span>`;root.dataset.exportKind=format;}
  function updatePreview(){clearTimeout(previewTimer);previewTimer=setTimeout(()=>{const iframe=document.querySelector('.ex15-paper iframe');if(!iframe||!A()?.data())return;iframe.addEventListener('load',()=>iframe.parentElement?.querySelector('.ex15-paper-loading')?.remove(),{once:true});const d=new DOMParser().parseFromString(window.YV_V3.exportHTML('string'),'text/html');d.querySelectorAll('script,.document-actions').forEach(n=>n.remove());const style=d.createElement('style');style.textContent='html{overflow:hidden}body{background:#fff!important}main{margin:0!important;max-width:none!important;box-shadow:none!important;border:0!important}';d.head.append(style);iframe.srcdoc='<!doctype html>'+d.documentElement.outerHTML;},70);}
  function setTab(value,focus=false){activeTab=['export','review','figures'].includes(value)?value:'export';const root=document.querySelector('.ex15-review');if(!root)return;root.querySelectorAll('[data-ex15-tab]').forEach(b=>{const on=b.dataset.ex15Tab===activeTab;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;});root.querySelectorAll('[data-ex15-panel]').forEach(p=>p.hidden=p.dataset.ex15Panel!==activeTab);if(focus)root.querySelector(`[data-ex15-tab="${activeTab}"]`)?.focus();if(activeTab==='export'&&!root.querySelector('.ex15-paper iframe')?.srcdoc)updatePreview();}
  function afterRender(){const root=document.querySelector('#plan-workbench[data-plan-phase="review"]');if(!root||root.dataset.ex15Ready)return;window.YV_PLAN_PREVIEW.afterRender();const content=root.querySelector('.pw-content'),exportSection=content.querySelector('.pw-export');if(!exportSection)return;root.dataset.ex15Ready='true';const original=[...content.children],mapSection=original.find(n=>n.querySelector('.pw-mindmap')),resultSection=original.find(n=>n.classList.contains('pv13-result-entry'));const shell=document.createElement('div');shell.className='ex15-review';shell.innerHTML=`<nav class="ex15-tabs" role="tablist" aria-label="${E(T('export'))}">${[['export','download'],['review','check'],['figures','workflow']].map(([key,icon])=>`<button type="button" role="tab" id="ex15-tab-${key}" aria-controls="ex15-panel-${key}" data-ex15-tab="${key}">${A().icon(icon)}${E(T(key))}</button>`).join('')}</nav>${['export','review','figures'].map(key=>`<section role="tabpanel" aria-labelledby="ex15-tab-${key}" id="ex15-panel-${key}" data-ex15-panel="${key}" ${key===activeTab?'':'hidden'}></section>`).join('')}`;content.replaceChildren(shell);exportSection.className='pw-export ex15-export';exportSection.innerHTML=exportMarkup();shell.querySelector('[data-ex15-panel="export"]').append(exportSection);const checks=shell.querySelector('[data-ex15-panel="review"]');checks.innerHTML=`<p class="ex15-panel-lead">${E(T('checksHint'))}</p>`;for(const node of original){if(node===exportSection)continue;if(node===mapSection||node===resultSection)shell.querySelector('[data-ex15-panel="figures"]').append(node);else checks.append(node);}if(mapSection){const head=mapSection.querySelector('.pw-section-head');head.querySelector('button')?.remove();head.insertAdjacentHTML('beforeend',button(A().icon('view')+E(T('preview')),'data-ex15="workflow"'));}const frame=shell.querySelector('.ex15-paper-frame'),resize=()=>{const width=frame.getBoundingClientRect().width;if(width)frame.querySelector('iframe').style.setProperty('--ex15-paper-scale',width/850);};paperObserver?.disconnect();paperObserver=new ResizeObserver(resize);paperObserver.observe(frame);updateFormat();setTab(activeTab);resize();}
  document.addEventListener('click',event=>{const tab=event.target.closest('[data-ex15-tab]');if(tab){setTab(tab.dataset.ex15Tab,true);return;}const action=event.target.closest('[data-ex15]')?.dataset.ex15;if(action==='preview')window.YV_PLAN_PREVIEW.open('document');if(action==='workflow')window.YV_PLAN_PREVIEW.open('workflow');const palette=event.target.closest('[data-ex15-theme]');if(palette){try{localStorage.setItem('yv.export.theme',palette.dataset.ex15Theme)}catch{}document.querySelectorAll('[data-ex15-theme]').forEach(b=>b.setAttribute('aria-pressed',String(b===palette)));updatePreview();}});
  document.addEventListener('change',event=>{const target=event.target;if(target.name==='ex15-format'){format=target.value;updateFormat();}if(target.hasAttribute('data-ex15-diagram')){diagram=target.value;updateFormat();}if(target.hasAttribute('data-ex15-citation')){citation=target.value;updateFormat();}});
  document.addEventListener('yv-export-options',()=>{document.querySelectorAll('.ex15-output [data-export-option]').forEach(n=>n.value=window.YV_EXPORT_LAYOUT.options()[n.dataset.exportOption]);updatePreview();});
  document.addEventListener('keydown',event=>{const tab=event.target.closest('[data-ex15-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const keys=['export','review','figures'],index=keys.indexOf(tab.dataset.ex15Tab),next=event.key==='Home'?0:event.key==='End'?keys.length-1:(index+(event.key==='ArrowRight'?1:-1)+keys.length)%keys.length;setTab(keys[next],true);});
  window.addEventListener('yv:planchange',()=>{const root=document.querySelector('#plan-workbench[data-plan-phase="review"]');if(!root)return;updatePreview();const entry=root.querySelector('.pv13-result-entry');if(entry)root.querySelector('[data-ex15-panel="figures"]')?.append(entry);});
  window.YV_EXPORT_EXPERIENCE={afterRender,updatePreview,text:T,getState:()=>({tab:activeTab,format,diagram,citation})};
})();
